```json
{
  "title": "Đà Lạt thong thả, cà phê ngắm phố",
  "summary": "Ngày bớt đi bộ, thêm thời gian ngồi xuống: chợ, vườn hoa, một quán cà phê view đẹp và hai bữa ăn trọn vị Đà Lạt.",
  "stops": [
    {
      "poi_id": "p165",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chợ Đà Lạt buổi sáng vẫn đông vui, đi một vòng nghe người ta trả giá là đủ vị phố núi."
    },
    {
      "poi_id": "p286",
      "kind": "activity",
      "must_do_id": null,
      "note": "Vườn hoa gần chợ, không phải cuốc bộ xa, đứng giữa hoa mà hít thở cho chậm lại."
    },
    {
      "poi_id": "p191",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bánh căn nóng giòn, ngồi xuống ăn từ tốn, ngon quá (so tasty) là phải nói cho cô chủ nghe."
    },
    {
      "poi_id": "p49",
      "kind": "activity",
      "must_do_id": null,
      "note": "Thêm một quán cà phê view đẹp, ngồi lâu một chút, khỏi đi bộ nhiều mà vẫn thấy Đà Lạt bên dưới."
    },
    {
      "poi_id": "p33",
      "kind": "meal",
      "must_do_id": null,
      "note": "Bữa tối ngồi lại cho đàng hoàng, ăn chậm, nhìn phố lên đèn, tối ở đây hiền lắm."
    }
  ]
}
```

